INSERT INTO public.requirement_items
    (id, country_code, purpose, pillar, title, description, severity, owner, required_fields_json, citations_json, applies_to_nationality_classes_json, non_obvious, timing, verification_status, review_status, last_verified_at)
VALUES
    ('ie_arrival_sequence_emergency_tax_rates', 'IRELAND', 'employment', 'TIMELINE', 'If an employee has given their PPSN to their employer but their job has not been registered with Revenue, Emergency Tax applies: 20% on income up to the standard rate band in we…', 'If an employee has given their PPSN to their employer but their job has not been registered with Revenue, Emergency Tax applies: 20% on income up to the standard rate band in weeks 1–4, then 40% on all income from week 5 onward. Without a PPSN at all, 40% tax applies immediately on all income. The emergency USC rate is a flat 8%.', 'WARN', 'EMPLOYEE', '[]', '[{"url": "https://www.revenue.ie/en/jobs-and-pensions/emergency-tax/emergency-tax-rules.aspx", "source_name": "revenue.ie", "topic_key": "arrival_sequence", "domain_area": "timeline", "source_tier": "semi_official", "evidence_quote": "When you are on Emergency Tax, the rate you pay depends on if you have provided your Personal Public Service Number (PPSN) to your employer. Your employer will tax all your pay at the higher rate of tax (40%) [if no PPSN]. From Week 5 onwards, your full income will be taxed at the higher rate (40%). The emergency rate of USC is a flat percentage rate (8% in 2026) applied to all income.", "added_date": "2026-08-31"}]', NULL, TRUE, 'Emergency Tax applies from the first pay day if job is not registered with Revenue; week 5 cut-off triggers full 40% rate even if PPSN has been provided', 'representative', 'pending', NOW()),
    ('ie_arrival_sequence_irp_late_registration_consequence', 'IRELAND', 'employment', 'TIMELINE', 'Non-EEA employees who cannot secure an IRP registration appointment within 90 days of arrival will not have their permission cancelled while waiting, provided they can demonstra…', 'Non-EEA employees who cannot secure an IRP registration appointment within 90 days of arrival will not have their permission cancelled while waiting, provided they can demonstrate they sought an appointment within the 90-day window — however, a person seeking to register beyond a reasonable time may be refused and issued with an intention-to-deport notification. Failure to register is an offence under Section 9 of the Immigration Act 2004.', 'WARN', 'EMPLOYEE', '[]', '[{"url": "https://www.irishimmigration.ie/registering-your-immigration-permission/frequently-asked-questions-for-registration/", "source_name": "irishimmigration.ie", "topic_key": "arrival_sequence", "domain_area": "timeline", "source_tier": "official", "evidence_quote": "A person seeking to register beyond a reasonable time may be refused and issued with an intention to deport notification. However, if you cannot get an appointment within this period do not worry, as we will not cancel your permission or expect you to leave the country while you are waiting to register.", "added_date": "2026-08-31"}]', NULL, TRUE, 'Register within 90 days of arrival in Ireland; offence under Section 9 Immigration Act 2004 if non-compliant without reasonable cause', 'representative', 'pending', NOW()),
    ('ie_arrival_sequence_myaccount_ppsn_prerequisite', 'IRELAND', 'employment', 'TIMELINE', 'Revenue myAccount cannot be set up before the PPSN is received: a PPSN is a mandatory prerequisite for myAccount registration', 'Revenue myAccount cannot be set up before the PPSN is received: a PPSN is a mandatory prerequisite for myAccount registration. Without myAccount, a new employee cannot register their job with Revenue and will be placed on Emergency Tax. Employees should contact DSP immediately after starting work to expedite PPSN allocation.', 'WARN', 'EMPLOYEE', '[]', '[{"url": "https://www.revenue.ie/en/online-services/services/myaccount/register-for-myaccount.aspx", "source_name": "revenue.ie", "topic_key": "arrival_sequence", "domain_area": "timeline", "source_tier": "semi_official", "evidence_quote": "To register for myAccount, you will need your: Personal Public Service Number (PPSN), date of birth, phone number (mobile or landline), email address, home address.", "added_date": "2026-08-31"}]', NULL, TRUE, 'PPSN must be obtained before myAccount can be activated; register job on myAccount before first pay day to avoid Emergency Tax', 'representative', 'pending', NOW()),
    ('ie_fintech_bridge_revolut_no_address_proof_required', 'IRELAND', 'employment', 'IDENTITY', 'Revolut Ireland account opening does not require traditional proof of address — identity is verified with a government-issued photo ID and selfie', 'Revolut Ireland account opening does not require traditional proof of address — identity is verified with a government-issued photo ID and selfie. A temporary Irish address (such as a hotel or hostel, with a valid Eircode) can be provided and updated later. This makes Revolut accessible as a day-1 bridge account for new arrivals without a permanent Irish address.', 'WARN', 'EMPLOYEE', '[]', '[{"url": "https://www.revolut.com/en-IE/blog/post/how-to-open-a-bank-account-in-ireland/", "source_name": "revolut.com", "topic_key": "fintech_bridge", "domain_area": "banking", "source_tier": "unofficial", "evidence_quote": "For Revolut Ireland, no proof of Irish address is required for e-money onboarding—a temporary Irish address with a valid Eircode (such as a hostel or hotel) may be used and updated later. You can verify your identity using a passport or driver''s licence with a quick selfie.", "added_date": "2026-08-31"}]', NULL, TRUE, 'Account can be opened before obtaining a permanent Irish address; provide any valid Eircode initially', 'representative', 'pending', NOW()),
    ('ie_gp_registration_ehic_visitor_coverage', 'IRELAND', 'employment', 'HEALTHCARE', 'An EHIC from another EU/EEA country covers necessary medical treatment in Ireland free of charge, including access to PCRS-contracted GP practices, emergency hospital treatment …', 'An EHIC from another EU/EEA country covers necessary medical treatment in Ireland free of charge, including access to PCRS-contracted GP practices, emergency hospital treatment with no charge, and emergency dental treatment at HSE Dental Clinics. Prescribed medicines carry a €1.50 charge per item, capped at €15 per month per person. EHIC covers public healthcare only — it does not cover private healthcare.', 'WARN', 'EMPLOYEE', '[]', '[{"url": "https://www2.hse.ie/services/schemes-allowances/ehic/visitors-to-ireland/", "source_name": "2.hse.ie", "topic_key": "gp_registration", "domain_area": "healthcare", "source_tier": "official", "evidence_quote": "If you are visiting Ireland, you can get treatment by a PCRS doctor for free with an EHIC. If you have an EHIC, there''s no charge for hospital treatment. There''s a €1.50 charge for each item but you only pay up to €15 a month per person. If you have an EHIC you can access necessary emergency dental treatment through a local HSE Dental Clinic for free. An EHIC only covers public healthcare, it does not cover private healthcare.", "added_date": "2026-08-31"}]', NULL, TRUE, 'EHIC coverage is temporary and intended for visitors or transitional residents; apply for medical card or private insurance once ordinarily resident', 'representative', 'pending', NOW()),
    ('ie_gp_registration_hse_find_gp_tool', 'IRELAND', 'employment', 'HEALTHCARE', 'The HSE Find a GP tool is available at hse.ie and searches by name, address, or current location', 'The HSE Find a GP tool is available at hse.ie and searches by name, address, or current location. It lists GP practices with their address, phone number, and where available, email and website. The tool does not indicate which practices are accepting new patients; employees must contact practices directly to confirm availability.', 'INFO', 'EMPLOYEE', '[]', '[{"url": "https://www2.hse.ie/services/find-a-gp/", "source_name": "2.hse.ie", "topic_key": "gp_registration", "domain_area": "healthcare", "source_tier": "official", "evidence_quote": "Search by place. Enter a name or address and select an option from the list. Use your current location.", "added_date": "2026-08-31"}]', NULL, FALSE, 'Contact GP practices directly to confirm they are accepting new private patients before attending', 'representative', 'pending', NOW()),
    ('ie_iban_sepa_iban_discrimination_prohibited', 'IRELAND', 'employment', 'IDENTITY', 'IBAN discrimination is prohibited in Ireland: an Irish employer or utility company cannot insist that an employee open or maintain an Irish bank account for euro transfers', 'IBAN discrimination is prohibited in Ireland: an Irish employer or utility company cannot insist that an employee open or maintain an Irish bank account for euro transfers. Employers are obliged to accept IBANs from all SEPA participating countries. Non-compliance can be reported to the Central Bank at ibandiscrimination@centralbank.ie.', 'WARN', 'EMPLOYEE', '[]', '[{"url": "https://www.centralbank.ie/consumer-hub/explainers/what-is-iban-discrimination-and-what-can-i-do-about-it", "source_name": "centralbank.ie", "topic_key": "iban_sepa", "domain_area": "banking", "source_tier": "unofficial", "evidence_quote": "IBAN discrimination is where an employer or company, such as a utility company, refuses to accept your SEPA IBAN for euro payments or direct debits. An Irish employer or utility company cannot insist you open or maintain an Irish bank account for euro transfers.", "added_date": "2026-08-31"}]', NULL, TRUE, 'Obligation applies immediately; employees can insist on SEPA IBAN acceptance from day 1 of employment', 'representative', 'pending', NOW()),
    ('ie_iban_sepa_sepa_dd_8week_refund_authorised', 'IRELAND', 'employment', 'IDENTITY', 'Under SEPA direct debit rules, consumers in Ireland have an unconditional right to a refund of an authorised direct debit within 8 weeks of the debit date, without needing to pr…', 'Under SEPA direct debit rules, consumers in Ireland have an unconditional right to a refund of an authorised direct debit within 8 weeks of the debit date, without needing to provide a reason. After 8 weeks, the consumer may be asked to provide proof that they did not authorise the payment. For unauthorised debits, consumers should request a refund immediately.', 'WARN', 'EMPLOYEE', '[]', '[{"url": "https://www.ccpc.ie/consumers/money/banking/paying-bills/", "source_name": "ccpc.ie", "topic_key": "iban_sepa", "domain_area": "banking", "source_tier": "unofficial", "evidence_quote": "If more than eight weeks have passed, you may be asked to provide proof that you did not authorise the payment. If a direct debit is unauthorised, request a refund immediately.", "added_date": "2026-08-31"}]', NULL, TRUE, '8-week window for authorised SEPA direct debit refunds; request immediately for unauthorised debits', 'representative', 'pending', NOW()),
    ('ie_lease_deposit_rtb_deposit_scheme_not_commenced', 'IRELAND', 'employment', 'HOUSING', 'As of September 2025, Ireland has no operational state deposit protection scheme despite the Residential Tenancies (Amendment) Act 2015 providing for one', 'As of September 2025, Ireland has no operational state deposit protection scheme despite the Residential Tenancies (Amendment) Act 2015 providing for one. The Protection of Tenants'' Deposits Bill 2025 (a private member''s bill to compel commencement of the 2015 scheme) was introduced but as of September 2025 the underlying deposit protection scheme had still not been activated. Deposits remain held by landlords with no state escrow.', 'WARN', 'EMPLOYEE', '[]', '[{"url": "https://www.oireachtas.ie/en/bills/bill/2025/4/", "source_name": "oireachtas.ie", "topic_key": "lease_deposit_rtb", "domain_area": "housing", "source_tier": "unofficial", "evidence_quote": "The law was introduced in 2015 – but there''s still no sign of it actually happening. The Residential Tenancies (Amendment) Act 2015 provides for a tenancy deposit protection scheme, where the RTB would manage and hold deposits for tenants and landlords. These provisions are not yet in effect.", "added_date": "2026-08-31"}]', NULL, TRUE, 'No state deposit scheme operative as of August 2026; employees must rely on RTB dispute process to recover unreturned deposits', 'representative', 'pending', NOW()),
    ('ie_lease_deposit_rtb_register_check_eircode', 'IRELAND', 'employment', 'HOUSING', 'Employees can verify whether their rental property is registered with the RTB using the public register check tool at rtb.ie/check-the-register/', 'Employees can verify whether their rental property is registered with the RTB using the public register check tool at rtb.ie/check-the-register/. The search tool accepts an Eircode or address and returns address confirmation for registered tenancies. Landlord name is not a searchable field.', 'INFO', 'EMPLOYEE', '[]', '[{"url": "https://www.rtb.ie/check-the-register/", "source_name": "rtb.ie", "topic_key": "lease_deposit_rtb", "domain_area": "housing", "source_tier": "official", "evidence_quote": "Enter an Eircode to check if a tenancy is registered with the RTB. Step 1 - Enter your address or Eircode to check the register. Step 2 - Review the address details and search the register.", "added_date": "2026-08-31"}]', NULL, FALSE, 'Check before signing a lease; unregistered landlords face penalties and tenants may have reduced protections', 'representative', 'pending', NOW()),
    ('ie_medical_card_processing_15_days', 'IRELAND', 'employment', 'HEALTHCARE', 'The HSE processes completed medical card applications within 15 days', 'The HSE processes completed medical card applications within 15 days. Incomplete applications will be delayed: the HSE will write to the applicant specifying what information is missing. Applications can be submitted online via mymedicalcard.ie or by post.', 'INFO', 'EMPLOYEE', '[]', '[{"url": "https://www2.hse.ie/services/schemes-allowances/medical-cards/applying/after-you-apply-for-a-medical-card/", "source_name": "2.hse.ie", "topic_key": "medical_card", "domain_area": "healthcare", "source_tier": "official", "evidence_quote": "We process completed medical card applications within 15 days. If we don''t have all the information we need, we will write to you and let you know what is missing. This will delay the processing of your application.", "added_date": "2026-08-31"}]', NULL, FALSE, '15-day processing target applies to complete applications only; incomplete applications reset the clock', 'representative', 'pending', NOW()),
    ('ie_medical_card_under70_basic_rate_single', 'IRELAND', 'employment', 'HEALTHCARE', 'For medical card means-testing for persons aged under 65, the weekly basic rate allowance is €184 for a single person living alone, and €164 for a single person living with family', 'For medical card means-testing for persons aged under 65, the weekly basic rate allowance is €184 for a single person living alone, and €164 for a single person living with family. The total qualifying threshold is calculated by adding the basic rate plus allowances for dependants and allowable expenses (rent, work travel). Net weekly income below the threshold qualifies for a medical card.', 'WARN', 'EMPLOYEE', '[]', '[{"url": "https://www2.hse.ie/services/schemes-allowances/medical-cards/applying/how-much-you-can-earn/", "source_name": "2.hse.ie", "topic_key": "medical_card", "domain_area": "healthcare", "source_tier": "official", "evidence_quote": "Single person living alone aged up to 65: €184. Single person living with family aged up to 65: €164. Your qualifying financial threshold is calculated by adding the following 3 amounts: A basic rate - an amount of money depending on your circumstances. The amount allocated for each dependant. The amount for allowable expenses.", "added_date": "2026-08-31"}]', NULL, TRUE, 'Income threshold assessed on net weekly income after tax, PRSI and USC; check current figures at hse.ie as rates may change annually', 'representative', 'pending', NOW()),
    ('ie_pps_number_employer_letter_evidence_of_need', 'IRELAND', 'employment', 'IDENTITY', 'An employer letter is the explicitly required form of ''evidence of need'' for PPSN applications made for employment purposes', 'An employer letter is the explicitly required form of ''evidence of need'' for PPSN applications made for employment purposes. The letter must be signed, on company headed paper showing the employer''s contact details and company registered number, and must confirm when the job is due to start or has started.', 'WARN', 'EMPLOYEE', '[]', '[{"url": "https://www.gov.ie/en/service/12e6de-get-a-personal-public-service-pps-number/", "source_name": "gov.ie", "topic_key": "pps_number", "domain_area": "identity", "source_tier": "official", "evidence_quote": "If you are applying for a PPS Number to work in Ireland, you must have a signed offer of employment from your employer confirming when your job is due to start or when it started. This letter should be on company headed paper with the employer''s contact details and employer/company registered number.", "added_date": "2026-08-31"}]', NULL, TRUE, 'Employer letter must be provided at time of PPSN application appointment', 'representative', 'pending', NOW()),
    ('ie_pps_number_myaccount_requires_ppsn_first', 'IRELAND', 'employment', 'IDENTITY', 'Revenue myAccount cannot be registered until the PPSN is received', 'Revenue myAccount cannot be registered until the PPSN is received. Pre-registration is not possible: the PPSN is a mandatory field in the myAccount registration form. Employees without a PPSN will be placed on Emergency Tax until the PPSN is obtained and the job is registered.', 'WARN', 'EMPLOYEE', '[]', '[{"url": "https://www.revenue.ie/en/online-services/services/myaccount/register-for-myaccount.aspx", "source_name": "revenue.ie", "topic_key": "pps_number", "domain_area": "identity", "source_tier": "semi_official", "evidence_quote": "To register for myAccount, you will need your: Personal Public Service Number (PPSN), date of birth, phone number (mobile or landline), email address, home address.", "added_date": "2026-08-31"}]', NULL, TRUE, 'PPSN must be received before myAccount registration is possible; no partial pre-registration option exists', 'representative', 'pending', NOW()),
    ('ie_prescriptions_dps_hrt_free_from_june2025', 'IRELAND', 'employment', 'HEALTHCARE', 'From 1 June 2025, HRT prescribed to treat symptoms associated with menopause is available free of charge from participating pharmacies for women who hold a Drugs Payment Scheme …', 'From 1 June 2025, HRT prescribed to treat symptoms associated with menopause is available free of charge from participating pharmacies for women who hold a Drugs Payment Scheme (DPS) card or a GMS medical card and have a valid HRT prescription. The DPS card is required for women without a medical card. The State covers both medication costs and the pharmacy dispensing fee (€5 per item). Women can register for a DPS card online at mydps.ie.', 'WARN', 'EMPLOYEE', '[]', '[{"url": "https://www2.hse.ie/services/schemes-allowances/drugs-payment-scheme/card/", "source_name": "2.hse.ie", "topic_key": "prescriptions_dps", "domain_area": "healthcare", "source_tier": "official", "evidence_quote": "You will also need a DPS card to get free hormone replacement therapy (HRT). Free HRT will be available from 1 June. Anyone living in Ireland and intends to live here for at least 1 year can apply. There is no means test for a DPS card.", "added_date": "2026-08-31"}]', NULL, TRUE, 'Free HRT available from 1 June 2025; DPS card must be obtained in advance — apply online at mydps.ie', 'representative', 'pending', NOW()),
    ('ie_prescriptions_dps_lti_qualifying_conditions', 'IRELAND', 'employment', 'HEALTHCARE', 'The Long-Term Illness (LTI) Scheme provides free drugs, medicines, and medical appliances for 16 specific conditions with no means test', 'The Long-Term Illness (LTI) Scheme provides free drugs, medicines, and medical appliances for 16 specific conditions with no means test. Qualifying conditions are: acute leukaemia, cerebral palsy, cystic fibrosis, diabetes insipidus, diabetes mellitus (gestational excluded), epilepsy, haemophilia, hydrocephalus, intellectual disability, mental illness (under 16s only), muscular dystrophy, multiple sclerosis, Parkinsonism, phenylketonuria (PKU), spina bifida, and thalidomide-related conditions.', 'WARN', 'EMPLOYEE', '[]', '[{"url": "https://www2.hse.ie/services/schemes-allowances/lti/about/", "source_name": "2.hse.ie", "topic_key": "prescriptions_dps", "domain_area": "healthcare", "source_tier": "official", "evidence_quote": "The following 16 medical conditions are covered: Acute leukaemia, Cerebral palsy, Cystic fibrosis, Diabetes insipidus, Diabetes mellitus (Gestational diabetes excluded), Epilepsy, Haemophilia, Hydrocephalus, Intellectual disability, Mental illness (people under 16 years only), Muscular dystrophy, Multiple sclerosis (MS), Parkinsonism, Phenylketonuria (PKU), Spina bifida, Thalidomide-related conditions.", "added_date": "2026-08-31"}]', NULL, TRUE, 'Apply by downloading the LTI application form and including a medical report from a GP or consultant; send to HSE PCRS', 'representative', 'pending', NOW()),
    ('ie_prescriptions_dps_monthly_threshold', 'IRELAND', 'employment', 'HEALTHCARE', 'Under the Drugs Payment Scheme (DPS), individuals and families pay a maximum of €80 per calendar month for approved prescribed drugs, medicines, and appliances', 'Under the Drugs Payment Scheme (DPS), individuals and families pay a maximum of €80 per calendar month for approved prescribed drugs, medicines, and appliances. The DPS also covers rental costs for CPAP machines and oxygen. There is no means test; anyone living in Ireland intending to stay at least 1 year can apply. Applications can be made online at mydps.ie or by post.', 'INFO', 'EMPLOYEE', '[]', '[{"url": "https://www2.hse.ie/services/schemes-allowances/drugs-payment-scheme/card/", "source_name": "2.hse.ie", "topic_key": "prescriptions_dps", "domain_area": "healthcare", "source_tier": "official", "evidence_quote": "you or your family will pay a maximum of €80 in a calendar month for: approved prescribed drugs and medicines. Anyone living in Ireland and intends to live here for at least 1 year can apply. There is no means test for a DPS card.", "added_date": "2026-08-31"}]', NULL, FALSE, 'Monthly cap applies per calendar month; costs above €80 are refunded by HSE', 'representative', 'pending', NOW()),
    ('ie_private_insurance_lcr_childhood_cover_no_credit', 'IRELAND', 'employment', 'HEALTHCARE', 'Time spent covered as a child on a parent''s private health insurance policy does not count toward reducing an LCR loading', 'Time spent covered as a child on a parent''s private health insurance policy does not count toward reducing an LCR loading. LCR credit is only given for periods of coverage held in the individual''s own name. HR teams should advise employees who were covered as children under a parent''s policy that this does not reduce their LCR loading when they take out their first individual policy.', 'WARN', 'EMPLOYEE', '[]', '[{"url": "https://www.hia.ie/consumer-information/lifetime-community-rating-lcr", "source_name": "hia.ie", "topic_key": "private_insurance", "domain_area": "healthcare", "source_tier": "unofficial", "evidence_quote": "You won''t get credit for any cover that you had as a child.", "added_date": "2026-08-31"}]', NULL, TRUE, 'LCR loading is calculated based on age at first individual policy purchase; childhood dependent cover does not count', 'representative', 'pending', NOW()),
    ('ie_private_insurance_lcr_new_resident_9month_window', 'IRELAND', 'employment', 'HEALTHCARE', 'New residents moving to Ireland for the first time can purchase private health insurance within 9 months of becoming resident without incurring any Lifetime Community Rating (LC…', 'New residents moving to Ireland for the first time can purchase private health insurance within 9 months of becoming resident without incurring any Lifetime Community Rating (LCR) loading, regardless of their age. Acceptable evidence of residency includes foreign rental agreements, foreign bank statements, foreign utility bills, and travel documents. Evidence of planning to stay more than 9 months (e.g. work contract, rental agreement) is also required.', 'WARN', 'EMPLOYEE', '[]', '[{"url": "https://www.hia.ie/moving-to-ireland", "source_name": "hia.ie", "topic_key": "private_insurance", "domain_area": "healthcare", "source_tier": "unofficial", "evidence_quote": "If you move to Ireland for the first time and you buy health insurance within nine months of making Ireland your principal residence, you won''t have to pay a LCR loading. Evidence of your time spent living abroad (foreign rental agreements, foreign bank statements, foreign utility bills). Evidence that you are planning on staying in Ireland for more than nine months (work contract, proof of enrolment in an educational institution, rental agreement, mortgage agreement, utility bill).", "added_date": "2026-08-31"}]', NULL, TRUE, 'Must purchase health insurance within 9 months of establishing principal residence in Ireland to avoid LCR loading', 'representative', 'pending', NOW()),
    ('ie_private_insurance_tax_relief_at_source', 'IRELAND', 'employment', 'HEALTHCARE', 'Tax relief on private health insurance premiums in Ireland is granted at source (TRS) at the standard rate of tax (20%)', 'Tax relief on private health insurance premiums in Ireland is granted at source (TRS) at the standard rate of tax (20%). The insurance company deducts the relief from the premium before charging the policyholder, so no separate Revenue claim is needed. Relief is capped at 20% of €1,000 per adult (maximum credit €200) and 20% of €500 per child (maximum credit €100).', 'WARN', 'EMPLOYEE', '[]', '[{"url": "https://www.revenue.ie/en/personal-tax-credits-reliefs-and-exemptions/health-and-age/medical-insurance-premiums/index.aspx", "source_name": "revenue.ie", "topic_key": "private_insurance", "domain_area": "healthcare", "source_tier": "semi_official", "evidence_quote": "The tax relief you can claim is at the standard rate of tax (20%). Relief is available at the rate of tax relief applicable to your health insurance policy on the lesser of either: the cost of the policy [or] up to 20% of €1,000 (up to a maximum credit of €200). [For children:] up to 20% of €500 (up to a maximum credit of €100).", "added_date": "2026-08-31"}]', NULL, TRUE, 'Relief applied automatically at point of premium payment; no annual tax return needed for TRS claims', 'representative', 'pending', NOW()),
    ('ie_proof_of_address_aib_fintech_not_accepted', 'IRELAND', 'employment', 'IDENTITY', 'AIB requires proof of address from a regulated financial institution operating in the Republic of Ireland', 'AIB requires proof of address from a regulated financial institution operating in the Republic of Ireland. A letter from the DSP Client Identity Services confirming a PPSN is explicitly excluded as acceptable proof of address for account opening. Financial institution correspondence must come from an Irish-regulated entity, meaning statements from fintechs regulated solely in other EU jurisdictions may not be accepted.', 'WARN', 'EMPLOYEE', '[]', '[{"url": "https://www.aib.ie/our-products/savings-and-deposits/personal-identification-requirements", "source_name": "aib.ie", "topic_key": "proof_of_address", "domain_area": "identity", "source_tier": "unofficial", "evidence_quote": "Correspondence from a Regulated Financial Institution operating in the Republic of Ireland (Insurance / Assurance Co., Bank, Building Society, Credit Union, Credit Card Company). Documents must be issued to you at your home address within the past 6 months. A Personal Public Service (PPS) Letter issued by the Irish Client Identity Services Department...are not acceptable.", "added_date": "2026-08-31"}]', NULL, TRUE, 'Address documents must be issued within the past 6 months at time of AIB account application', 'representative', 'pending', NOW()),
    ('ie_proof_of_address_boi_coming_to_ireland_docs', 'IRELAND', 'employment', 'IDENTITY', 'Bank of Ireland''s ''Coming to Ireland'' account accepts utility bills, financial statements, or letters from Revenue, an approved university, the CAO, the Department of Social Wel…', 'Bank of Ireland''s ''Coming to Ireland'' account accepts utility bills, financial statements, or letters from Revenue, an approved university, the CAO, the Department of Social Welfare, or the Naturalisation and Immigration Service as proof of address. Non-English documents must be certified by a registered notary public, practising legal professional, or embassy/government official.', 'WARN', 'EMPLOYEE', '[]', '[{"url": "https://personalbanking.bankofireland.com/bank/current-accounts/personal-current-account/coming-to-ireland/", "source_name": "personalbanking.bankofireland.com", "topic_key": "proof_of_address", "domain_area": "identity", "source_tier": "unofficial", "evidence_quote": "Proof of address – The documents we accept can include a utility bill, a financial statement, or a letter from the Revenue Commissioners, an approved university, the CAO, the Department of Social Welfare, or the Naturalisation and Immigration Service. Proof of address documents must be in English. If your documents are not in English, they must be translated & certified before you start the application.", "added_date": "2026-08-31"}]', NULL, TRUE, 'Address documents must be current at time of account application', 'representative', 'pending', NOW()),
    ('ie_proof_of_address_psc_safe_three_month_recency', 'IRELAND', 'employment', 'IDENTITY', 'For PSC/SAFE registration appointments, proof of address documents must show the applicant''s name and address and must not be older than 3 months', 'For PSC/SAFE registration appointments, proof of address documents must show the applicant''s name and address and must not be older than 3 months. This 3-month recency rule applies to all applicants regardless of nationality.', 'WARN', 'EMPLOYEE', '[]', '[{"url": "https://www.gov.ie/en/department-of-social-protection/publications/safe-registration-and-the-public-services-card-psc/", "source_name": "gov.ie", "topic_key": "proof_of_address", "domain_area": "identity", "source_tier": "official", "evidence_quote": "The document must show your name and address and not be older than 3 months.", "added_date": "2026-08-31"}]', NULL, TRUE, 'Address proof must be no older than 3 months at the date of the SAFE registration appointment', 'representative', 'pending', NOW()),
    ('ie_public_services_card_safe_address_proof_rule', 'IRELAND', 'employment', 'IDENTITY', 'Non-EU/EEA employees must attend a SAFE registration appointment in person and present their current passport as proof of identity', 'Non-EU/EEA employees must attend a SAFE registration appointment in person and present their current passport as proof of identity. The MyGovID app identity verification route requires an Irish passport and is therefore not available to non-Irish nationals. Proof of address documents must not be older than 3 months.', 'WARN', 'EMPLOYEE', '[]', '[{"url": "https://www.gov.ie/en/department-of-social-protection/publications/safe-registration-and-the-public-services-card-psc/", "source_name": "gov.ie", "topic_key": "public_services_card", "domain_area": "identity", "source_tier": "official", "evidence_quote": "Non-EU citizens need a current passport or 1951 travel document. The document must show your name and address and not be older than 3 months.", "added_date": "2026-08-31"}]', NULL, TRUE, 'In-person SAFE appointment required for non-Irish nationals; 3-month address proof recency rule applies', 'representative', 'pending', NOW()),
    ('ie_rental_market_rtb_non_registration_penalties', 'IRELAND', 'employment', 'HOUSING', 'Landlords who fail to register their tenancy with the RTB face serious penalties: criminal prosecution can result in fines of up to €4,000 and/or imprisonment for up to 6 months…', 'Landlords who fail to register their tenancy with the RTB face serious penalties: criminal prosecution can result in fines of up to €4,000 and/or imprisonment for up to 6 months, plus €250 per day the tenancy remains unregistered. Alternatively, the RTB can impose a civil sanction of up to €15,000 and €15,000 in costs per unregistered tenancy.', 'WARN', 'EMPLOYEE', '[]', '[{"url": "https://www.rtb.ie/register-tenancies/register-a-tenancy/consequences-of-not-registering/", "source_name": "rtb.ie", "topic_key": "rental_market", "domain_area": "housing", "source_tier": "official", "evidence_quote": "A criminal conviction. Fines of up to €4,000. Imprisonment for up to 6 months. €250 for each day the tenancy remains unregistered. A sanction of up to €15,000 and €15,000 in costs for each unregistered tenancy.", "added_date": "2026-08-31"}]', NULL, TRUE, 'Penalties accrue from the date registration was due; employees should verify RTB registration before signing a lease', 'representative', 'pending', NOW()),
    ('ie_rental_market_rtb_registration_fees_2026', 'IRELAND', 'employment', 'HOUSING', 'Landlords must register tenancies with the RTB annually', 'Landlords must register tenancies with the RTB annually. The standard fee is €40 per year for private, student-specific, and cost-rental tenancies. A late fee of €10 per month applies for each month the registration is late. Failure to register can result in criminal prosecution (fines up to €4,000 and/or imprisonment up to 6 months) or a civil sanction of up to €15,000 per unregistered tenancy.', 'INFO', 'EMPLOYEE', '[]', '[{"url": "https://www.rtb.ie/register-tenancies/register-a-tenancy/registration-fees/", "source_name": "rtb.ie", "topic_key": "rental_market", "domain_area": "housing", "source_tier": "official", "evidence_quote": "The standard fee to register is €40 a year. There is a late fee of €10 a month for each month that the registration is late.", "added_date": "2026-08-31"}]', NULL, FALSE, 'Register within 1 month of tenancy start to avoid late fees; annual renewal required', 'representative', 'pending', NOW()),
    ('ie_resident_account_opening_anpost_five_day_card', 'IRELAND', 'employment', 'IDENTITY', 'An Post Money current accounts are available to any person at least 16 years old, resident in the Republic of Ireland, with an Irish mobile number', 'An Post Money current accounts are available to any person at least 16 years old, resident in the Republic of Ireland, with an Irish mobile number. The debit card and account details are sent within 5 working days of approval. The account can be opened via the An Post Money app or at any post office. Proof of address must be dated within the last six months.', 'WARN', 'EMPLOYEE', '[]', '[{"url": "https://www.anpost.com/Money/Current-Account/How-to-Open-an-Account", "source_name": "anpost.com", "topic_key": "resident_account_opening", "domain_area": "banking", "source_tier": "unofficial", "evidence_quote": "we''ll send the account details and debit card within 5 working days. proof of address dated within the last six months (utility bill, bank statement or a letter from Revenue or Department of Social Protection). At least 16 years old, resident in the Republic of Ireland and have an Irish mobile number.", "added_date": "2026-08-31"}]', NULL, TRUE, 'Debit card delivered within 5 working days of account approval; apply via app or post office', 'representative', 'pending', NOW()),
    ('ie_tenant_rights_early_termination_fixed_term', 'IRELAND', 'employment', 'HOUSING', 'A tenant who ends a fixed-term lease early may face financial penalties', 'A tenant who ends a fixed-term lease early may face financial penalties. Permitted grounds for early termination without penalty are: a break clause in the lease; mutual agreement with the landlord; landlord breach of obligations not remedied within a reasonable time (usually 14 days); serious risk to life or property (7 days'' notice); or landlord refusal to allow sublet or assignment. There is no statutory ground for early termination due to immigration or visa change.', 'WARN', 'EMPLOYEE', '[]', '[{"url": "https://www.rtb.ie/renting/ending-a-tenancy/how-a-tenant-can-end-a-tenancy/", "source_name": "rtb.ie", "topic_key": "tenant_rights", "domain_area": "housing", "source_tier": "official", "evidence_quote": "If you end your fixed term tenancy earlier than agreed, you might have to pay penalties. There is a break clause: your lease allows ending the tenancy early. Both you and your landlord agree: to end the tenancy early. Landlord breach: your landlord has not met their responsibilities, and has not fixed the issue in a reasonable time (usually 14 days). Serious risk: if your landlord''s behaviour causes imminent danger to life, serious injury, or the structure of the property, you can give 7 days'' notice. Refusal to sublet: If your private landlord does not allow you to assign or sublet the property.", "added_date": "2026-08-31"}]', NULL, TRUE, 'Early termination without a break clause or mutual agreement exposes the tenant to financial liability; no immigration-based statutory exemption exists', 'representative', 'pending', NOW()),
    ('ie_tenant_rights_national_rent_cap_march2026', 'IRELAND', 'employment', 'HOUSING', 'From 1 March 2026, all Rent Pressure Zones (RPZs) were abolished and replaced by a single national rent control system', 'From 1 March 2026, all Rent Pressure Zones (RPZs) were abolished and replaced by a single national rent control system. Rent can only be increased once per year by 2% or the rate of inflation (CPI), whichever is lower. Newly built apartments with a commencement notice submitted on or after 10 June 2025 are exempt from the 2% cap and can track CPI without limit. Landlords must use the RTB Rent Calculator to calculate permissible increases.', 'WARN', 'EMPLOYEE', '[]', '[{"url": "https://rtb.ie/renting/rental-law-changes-from-1-march-2/", "source_name": "rtb.ie", "topic_key": "tenant_rights", "domain_area": "housing", "source_tier": "official", "evidence_quote": "From 1 March 2026, Rent Pressure Zones are replaced by a national system of rent control. Rent can only be increased once per year by 2% or rate of inflation (CPI) if lower. The 2% cap on annual rent increases does not apply to newly built apartments and student specific accommodation that commenced from 10 June 2025. You should use the RTB Rent Calculator to calculate the maximum rent increase allowed.", "added_date": "2026-08-31"}]', NULL, TRUE, 'New rules apply from 1 March 2026 to all existing and new tenancies; landlord must serve written notice with RTB calculator printout', 'representative', 'pending', NOW()),
    ('ie_tenant_rights_notice_periods_march2026', 'IRELAND', 'employment', 'HOUSING', 'From 1 March 2026, landlord notice periods under the Residential Tenancies (Miscellaneous Provisions) Act 2026 are: under 6 months tenancy — 90 days; 6 months to 1 year — 152 da…', 'From 1 March 2026, landlord notice periods under the Residential Tenancies (Miscellaneous Provisions) Act 2026 are: under 6 months tenancy — 90 days; 6 months to 1 year — 152 days; 1 year to 7 years — 180 days; 7 to 8 years — 196 days; over 8 years — 224 days. Shorter periods (28 days) apply for rent arrears and breach of obligations; 7 days for serious anti-social behaviour.', 'WARN', 'EMPLOYEE', '[]', '[{"url": "https://www.rtb.ie/renting/ending-a-tenancy/notice-of-termination-guide/", "source_name": "rtb.ie", "topic_key": "tenant_rights", "domain_area": "housing", "source_tier": "official", "evidence_quote": "The notice you need to give depends on how long the tenancy has been in place. Less than 6 months: 90 days. 6 months to 1 year: 152 days. 1 year to 7 years: 180 days. 7 years to 8 years: 196 days. More than 8 years: 224 days.", "added_date": "2026-08-31"}]', NULL, TRUE, 'Notice periods apply to all tenancies from 1 March 2026; correct period must be stated on the Notice of Termination', 'representative', 'pending', NOW()),
    ('ie_tenant_rights_rtb_dispute_28day_limit', 'IRELAND', 'employment', 'HOUSING', 'Disputes about rent amounts owed by a former tenant must be filed with the RTB within 28 days of the tenancy ending', 'Disputes about rent amounts owed by a former tenant must be filed with the RTB within 28 days of the tenancy ending. Disputes about breach of tenant obligations must also be filed within 28 days of the breach. Disputes about notice of termination validity must be filed within 90 days of receiving the notice (or 28 days if the tenant has breached obligations). The RTB Board may extend these limits in exceptional circumstances.', 'WARN', 'EMPLOYEE', '[]', '[{"url": "https://rtb.ie/disputes/guide-to-adjudication/", "source_name": "rtb.ie", "topic_key": "tenant_rights", "domain_area": "housing", "source_tier": "official", "evidence_quote": "Disputes about the rent amount that was agreed to or paid by a former tenant: Within 28 days of the tenancy ending. If you have met your tenant obligations, within 90 days of receiving the notice. If you have broken your tenant obligations, within 28 days. The RTB may extend these limits in exceptional circumstances. The RTB Board must consider and approve all requests to allow a late application.", "added_date": "2026-08-31"}]', NULL, TRUE, '28-day filing deadline from tenancy end for most breach/rent disputes; 90-day window for notice of termination disputes where tenant is not in breach', 'representative', 'pending', NOW())
